/**
 * n8n Code Node
 * Modo: Run Once for All Items
 *
 * Nos esperados:
 * - Read Base
 * - Read Stock
 * - Read Sales - Store A
 * - Read Sales - Store B
 * - Read Sales - Store C
 *
 * Saida:
 * Cod Componente
 * Descricao
 * Qcx
 * Cx
 * Jg
 * Dec
 * Un
 * Comp
 * On
 * Total
 * Media M
 * Qtd Estoque Jg
 * Qtd Estoque CX_UN
 * Encontrado na Base
 * Total Estoque
 */

// ======================================================
// CONFIGURACOES
// ======================================================

const PERIODOS_MEDIA = 3;

const USAR_QTDE_FATURADA = false;

const NOMES_NO_BASE = ['Read Base'];
const NOMES_NO_ESTOQUE = ['Read Stock'];

const NOS_VENDAS = [
  ['Read Sales - Store A'],
  ['Read Sales - Store B'],
  ['Read Sales - Store C'],
];

const PRIORIDADE_TIPO = {
  Cx: 1,
  Jg: 2,
  Dec: 3,
  Un: 4,
  Comp: 5,
};


// ======================================================
// FUNCOES GERAIS
// ======================================================

function removerAcentos(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizarNomeCampo(nome) {
  return removerAcentos(nome)
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function normalizarCodigo(valor) {
  return removerAcentos(String(valor || ''))
    .trim()
    .toUpperCase();
}

function normalizarTexto(valor) {
  return String(valor === null || valor === undefined ? '' : valor).trim();
}

function numero(valor, padrao = 0) {
  if (valor === null || valor === undefined || valor === '') return padrao;

  let texto = String(valor).trim();

  if (!texto) return padrao;

  if (texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  }

  const n = Number(texto);
  return Number.isFinite(n) ? n : padrao;
}

function arredondar(valor) {
  const n = Number(valor || 0);
  return Math.round((n + Number.EPSILON) * 1000000) / 1000000;
}

function mapaCampos(obj) {
  const mapa = {};

  for (const chave of Object.keys(obj || {})) {
    mapa[normalizarNomeCampo(chave)] = chave;
  }

  return mapa;
}

function pegarCampo(obj, aliases) {
  if (!obj) return '';

  const mapa = mapaCampos(obj);

  for (const alias of aliases) {
    const chave = mapa[normalizarNomeCampo(alias)];

    if (chave !== undefined) {
      return normalizarTexto(obj[chave]);
    }
  }

  return '';
}

function simplificarDescricao(texto) {
  let desc = normalizarTexto(texto);

  desc = desc
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\b\d+\s*(UN|UND|UNIDADE|UNIDADES|PC|PCS|PÇ|PÇS)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return desc || normalizarTexto(texto);
}

function lerNoComAlternativas(nomes) {
  const erros = [];

  for (const nome of nomes) {
    try {
      const itens = $(nome).all();

      if (itens && itens.length) {
        return itens.map(item => item.json || {});
      }

      erros.push(`No "${nome}" retornou vazio`);
    } catch (error) {
      erros.push(`No "${nome}" nao encontrado`);
    }
  }

  throw new Error(`Nao consegui ler nenhum destes nos: ${nomes.join(', ')}. Detalhes: ${erros.join(' | ')}`);
}

function criarLinhaAgregada(codComponente, descricao, qcx, encontrado) {
  return {
    codComponente,
    descricao: simplificarDescricao(descricao),
    qcx: qcx || 1,
    cx: 0,
    jg: 0,
    dec: 0,
    un: 0,
    comp: 0,
    on: 0,
    estoqueJg: 0,
    estoque: 0,
    encontradoNaBase: encontrado ? 'Sim' : 'Nao',
  };
}

function chaveAgregado(codComponente) {
  return normalizarCodigo(codComponente);
}


// ======================================================
// LEITURA DOS NOS
// ======================================================

const baseRows = lerNoComAlternativas(NOMES_NO_BASE);
const estoqueRows = lerNoComAlternativas(NOMES_NO_ESTOQUE);

const vendasRows = [];

for (const alternativas of NOS_VENDAS) {
  const linhas = lerNoComAlternativas(alternativas);
  vendasRows.push(...linhas);
}


// ======================================================
// VALIDACOES MINIMAS
// ======================================================

if (!baseRows.length) {
  throw new Error('Base vazia.');
}

if (!vendasRows.length) {
  throw new Error('Nenhuma venda encontrada.');
}

if (!estoqueRows.length) {
  throw new Error('Estoque vazio.');
}


// ======================================================
// CRIACAO DO INDICE DA BASE
// Cada codigo comercial aponta para um Cod Componente central
// ======================================================

const indiceCodigos = new Map();
const infoComponente = new Map();

function adicionarAoIndice(codigo, tipo, row, multiplicador) {
  const cod = normalizarCodigo(codigo);
  const codComponente = normalizarCodigo(pegarCampo(row, ['Cod Componente']));

  if (!cod || !codComponente) return;

  const descricao =
    pegarCampo(row, ['Descricao']) ||
    pegarCampo(row, ['Descricao do componente']);

  const qtdCx = numero(pegarCampo(row, ['Qtd Cx', 'Qtde Cx']), 1) || 1;
  const multiplicadorFinal = numero(multiplicador, 1) || 1;

  if (!infoComponente.has(codComponente)) {
    infoComponente.set(codComponente, {
      codComponente,
      descricao,
      qcx: qtdCx,
      encontrado: true,
    });
  } else {
    const info = infoComponente.get(codComponente);

    if (!info.descricao && descricao) info.descricao = descricao;
    if ((!info.qcx || info.qcx === 1) && qtdCx) info.qcx = qtdCx;
  }

  if (!indiceCodigos.has(cod)) {
    indiceCodigos.set(cod, []);
  }

  const lista = indiceCodigos.get(cod);

  const existente = lista.find(item =>
    item.tipo === tipo &&
    item.codComponente === codComponente
  );

  if (existente) {
    if (multiplicadorFinal > (existente.multiplicador || 1)) {
      existente.multiplicador = multiplicadorFinal;
    }

    if (!existente.descricao && descricao) {
      existente.descricao = descricao;
    }

    if ((!existente.qcx || existente.qcx === 1) && qtdCx) {
      existente.qcx = qtdCx;
    }

    return;
  }

  lista.push({
    codigo: cod,
    tipo,
    codComponente,
    descricao,
    multiplicador: multiplicadorFinal,
    qcx: qtdCx,
  });
}

for (const row of baseRows) {
  const codComponente = pegarCampo(row, ['Cod Componente']);
  const codCx = pegarCampo(row, ['Cod Cx']);
  const codJg = pegarCampo(row, ['Cod Jg']);
  const codDec = pegarCampo(row, ['Cod Dec']);
  const codComposicao = pegarCampo(row, ['Cod Composicao']);

  const qtdCx = numero(pegarCampo(row, ['Qtd Cx', 'Qtde Cx']), 1) || 1;

  const qtdJg = numero(
    pegarCampo(row, [
      'Qtd Jg',
      'Qtde Jg',
      'Qtd Jogo',
      'Qtde Jogo',
      'Quantidade Jg',
      'Quantidade Jogo'
    ]),
    1
  ) || 1;

  const qtdComp = numero(
    pegarCampo(row, [
      'Qtd Comp',
      'Qtde Comp',
      'Qtd Componente',
      'Qtde Componente',
      'Quantidade do Componente'
    ]),
    1
  ) || 1;

  adicionarAoIndice(codComponente, 'Un', row, 1);
  adicionarAoIndice(codCx, 'Cx', row, qtdCx);
  adicionarAoIndice(codJg, 'Jg', row, qtdJg);
  adicionarAoIndice(codDec, 'Dec', row, 1);
  adicionarAoIndice(codComposicao, 'Comp', row, qtdComp);
}

function resolverCodigo(codigo) {
  const cod = normalizarCodigo(codigo);

  if (!cod) {
    return {
      encontrado: false,
      tipo: 'Un',
      codComponente: '',
      descricao: '',
      multiplicador: 1,
      qcx: 1,
    };
  }

  const opcoes = indiceCodigos.get(cod);

  if (!opcoes || !opcoes.length) {
    return {
      encontrado: false,
      tipo: 'Un',
      codComponente: cod,
      descricao: '',
      multiplicador: 1,
      qcx: 1,
    };
  }

  const ordenadas = [...opcoes].sort((a, b) => {
    const prioridadeA = PRIORIDADE_TIPO[a.tipo] || 99;
    const prioridadeB = PRIORIDADE_TIPO[b.tipo] || 99;

    if (prioridadeA !== prioridadeB) {
      return prioridadeA - prioridadeB;
    }

    return (b.multiplicador || 1) - (a.multiplicador || 1);
  });

  const escolhido = ordenadas[0];

  return {
    encontrado: true,
    tipo: escolhido.tipo,
    codComponente: escolhido.codComponente,
    descricao: escolhido.descricao,
    multiplicador: escolhido.multiplicador || 1,
    qcx: escolhido.qcx || 1,
  };
}


// ======================================================
// AGREGACAO
// ======================================================

const agregados = new Map();

function obterAgregado(resolvido, descricaoFallback = '') {
  const codComponente = normalizarCodigo(resolvido.codComponente);

  if (!codComponente) return null;

  const chave = chaveAgregado(codComponente);

  if (!agregados.has(chave)) {
    const infoBase = infoComponente.get(codComponente);

    const descricao =
      (infoBase && infoBase.descricao) ||
      resolvido.descricao ||
      descricaoFallback ||
      codComponente;

    const qcx =
      (infoBase && infoBase.qcx) ||
      resolvido.qcx ||
      1;

    agregados.set(
      chave,
      criarLinhaAgregada(
        codComponente,
        descricao,
        qcx,
        resolvido.encontrado
      )
    );
  } else {
    const atual = agregados.get(chave);

    if (resolvido.encontrado) {
      atual.encontradoNaBase = 'Sim';
    }

    if ((!atual.descricao || atual.descricao === atual.codComponente) && descricaoFallback) {
      atual.descricao = simplificarDescricao(descricaoFallback);
    }

    if ((!atual.qcx || atual.qcx === 1) && resolvido.qcx) {
      atual.qcx = resolvido.qcx;
    }
  }

  return agregados.get(chave);
}


// ======================================================
// PROCESSAR VENDAS
// ======================================================

for (const row of vendasRows) {
  const codigoVenda = pegarCampo(row, ['Codigo']);
  const descricaoVenda = pegarCampo(row, ['Descricao']);

  const qtd = USAR_QTDE_FATURADA
    ? numero(pegarCampo(row, ['Qtde faturada', 'Qtd faturada']), 0)
    : numero(pegarCampo(row, ['Qtde', 'Qtd']), 0);

  if (!codigoVenda || !qtd) continue;

  const numeroLoja = pegarCampo(row, ['numeroLoja', 'Numero Loja', 'NumeroLoja']);
  const vendaOnline = numeroLoja !== '';

  const resolvido = resolverCodigo(codigoVenda);

  if (!resolvido.descricao && descricaoVenda) {
    resolvido.descricao = descricaoVenda;
  }

  const agregado = obterAgregado(resolvido, descricaoVenda);
  if (!agregado) continue;

  const qtdConvertida = qtd * (resolvido.multiplicador || 1);

  if (resolvido.tipo === 'Cx') {
    agregado.cx += qtdConvertida;
  } else if (resolvido.tipo === 'Jg') {
    agregado.jg += qtdConvertida;
  } else if (resolvido.tipo === 'Dec') {
    agregado.dec += qtdConvertida;
  } else if (resolvido.tipo === 'Comp') {
    agregado.comp += qtdConvertida;
  } else {
    agregado.un += qtdConvertida;
  }

  if (vendaOnline) {
    agregado.on += qtdConvertida;
  }
}


// ======================================================
// PROCESSAR ESTOQUE
// ======================================================

for (const row of estoqueRows) {
  const codigoEstoque = pegarCampo(row, ['Codigo']);
  const descricaoEstoque = pegarCampo(row, ['Descricao']);
  const quantidade = numero(pegarCampo(row, ['Quantidade', 'Qtde', 'Qtd']), 0);

  if (!codigoEstoque) continue;

  const codigoEstoqueNormalizado = normalizarCodigo(codigoEstoque);

  if (codigoEstoqueNormalizado.startsWith('VB')) {
    continue;
  }

  const resolvido = resolverCodigo(codigoEstoque);

  if (!resolvido.descricao && descricaoEstoque) {
    resolvido.descricao = descricaoEstoque;
  }

  let multiplicadorEstoque = resolvido.multiplicador || 1;

  const itensPorCaixaEstoque = numero(
    pegarCampo(row, [
      'itensPorCaixa',
      'Itens por Caixa',
      'ItensPorCaixa',
      'Itens por caixa',
      'Qtd por Caixa',
      'Qtde por Caixa'
    ]),
    0
  );

  if (resolvido.tipo === 'Jg' && itensPorCaixaEstoque > multiplicadorEstoque) {
    multiplicadorEstoque = itensPorCaixaEstoque;
  }

  if (!resolvido.encontrado) {
    multiplicadorEstoque = itensPorCaixaEstoque || 1;
  }

  const agregado = obterAgregado(resolvido, descricaoEstoque);
  if (!agregado) continue;

  const estoqueConvertido = quantidade * multiplicadorEstoque;

  if (resolvido.tipo === 'Jg') {
    agregado.estoqueJg += estoqueConvertido;
  }

  agregado.estoque += estoqueConvertido;
}


// ======================================================
// GERAR SAIDA
// ======================================================

const saida = [...agregados.values()]
  .sort((a, b) => {
    return String(a.codComponente).localeCompare(String(b.codComponente), 'pt-BR', {
      numeric: true,
      sensitivity: 'base',
    });
  })
  .map(item => {
    const total = item.cx + item.jg + item.dec + item.un + item.comp;
    const mediaM = Math.ceil(total / PERIODOS_MEDIA);

    const qtdEstoqueJg = item.estoqueJg;
    const totalEstoque = item.estoque;
    const qtdEstoqueCxUn = totalEstoque - qtdEstoqueJg;

   return {
  json: {
    'Cod Componente': item.codComponente,
    'Descricao': item.descricao,
    'Qcx': arredondar(item.qcx || 1),
    'Cx': arredondar(item.cx),
    'Jg': arredondar(item.jg),
    'Dec': arredondar(item.dec),
    'Un': arredondar(item.un),
    'Comp': arredondar(item.comp),
    'On': arredondar(item.on),
    'Total': arredondar(total),
    'Media M': mediaM,
    'Qtd Estoque Jg': arredondar(qtdEstoqueJg),
    'Qtd Estoque CX_UN': arredondar(qtdEstoqueCxUn),
    'Total Estoque': arredondar(totalEstoque),
    'Encontrado na Base': item.encontradoNaBase,
  },
};
  });

return saida;
